import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.ChTAMbUy.js";const p=JSON.parse('{"title":"Agent Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"development/platform/agent_gateway.md","filePath":"versions/development/platform/agent_gateway.md","lastUpdated":1787837970000}'),r={name:"development/platform/agent_gateway.md"};function n(i,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-gateway" tabindex="-1">Agent Gateway <a class="header-anchor" href="#agent-gateway" aria-label="Permalink to &quot;Agent Gateway&quot;">​</a></h1><p>Agent Gateway is the shared routing and policy layer for external API traffic in prokube, built on <a href="https://agentgateway.dev/" target="_blank" rel="noreferrer">agentgateway</a>, an AI-native Gateway API implementation. It gives SDKs, automation, CI jobs, and agent clients a single, API-key-authenticated way to reach model, tool, agent, and sandbox endpoints running in a workspace, without a browser session and without exposing each service through its own ad hoc ingress.</p><div class="info custom-block"><p class="custom-block-title">Upstream references</p><ul><li><a href="https://agentgateway.dev/docs/" target="_blank" rel="noreferrer">agentgateway documentation</a></li><li><a href="https://agentgateway.dev/docs/kubernetes/latest" target="_blank" rel="noreferrer">agentgateway on Kubernetes</a></li></ul></div><p>Agent Gateway is not an agent-only feature. The same routing and policy model fronts classic model-serving endpoints, Knative services, MCP servers, memory stores, kagent A2A agents, and Agent Sandboxes. It&#39;s a Foundation-level concept used by <a href="./../mlops/model_serving.html">MLOps</a>, <a href="./../agentops/agent_gateway.html">AgentOps</a>, and <a href="./../labs/opencode.html">Labs</a> alike. This page covers the shared routing model. For the AgentOps-specific view (how it moves traffic between agents, tools, and models), see <a href="./../agentops/agent_gateway.html">Agent Gateway for AgentOps</a>.</p><h2 id="when-to-use-agent-gateway" tabindex="-1">When to Use Agent Gateway <a class="header-anchor" href="#when-to-use-agent-gateway" aria-label="Permalink to &quot;When to Use Agent Gateway&quot;">​</a></h2><ul><li>Call model-serving endpoints from an external application, script, or CI job.</li><li>Give an agent access to a sandbox API without handing it browser credentials.</li><li>Expose MCP servers or memory stores to external agent clients.</li><li>Reach kagent agents through agent-to-agent (A2A) calls from outside the cluster.</li><li>Call a Knative-served endpoint from outside the platform.</li></ul><p>This list is not exhaustive: any external, API-key-authenticated call to a workspace service goes through Agent Gateway.</p><p>For interactive work in the prokube UI, use your normal user session instead. Agent Gateway is for programmatic clients.</p><h2 id="path-families" tabindex="-1">Path Families <a class="header-anchor" href="#path-families" aria-label="Permalink to &quot;Path Families&quot;">​</a></h2><p>Agent Gateway exposes one public path family per service type. Each path is workspace-scoped and requires an API key with a matching scope.</p><table tabindex="0"><thead><tr><th>Family</th><th>Path pattern</th><th>Backed by</th></tr></thead><tbody><tr><td><code>/ai</code></td><td><code>/ai/&lt;workspace&gt;/models/&lt;route-id&gt;/v1/...</code></td><td>OpenAI-compatible LLM traffic (chat completions, embeddings, rerank): self-hosted models deployed through <a href="./../agentops/llm_serving.html">LLM Serving</a>, and <a href="./../admin/external_models.html">external models</a> granted by an administrator. Classic (non-LLM) KServe models never use this family.</td></tr><tr><td><code>/serving</code></td><td><code>/serving/&lt;workspace&gt;/&lt;name&gt;</code></td><td>Classic KServe InferenceServices (V1/V2 predict protocol) and Knative Services. Both share this one path family: <code>&lt;name&gt;</code> resolves against whichever resource matches.</td></tr><tr><td><code>/mcp</code></td><td><code>/mcp/&lt;workspace&gt;/&lt;server&gt;</code></td><td>MCP servers and MCP-compatible memory stores</td></tr><tr><td><code>/a2a</code></td><td><code>/a2a/&lt;workspace&gt;/&lt;agent&gt;</code></td><td>kagent agent-to-agent access</td></tr><tr><td><code>/sandbox</code></td><td><code>/sandbox/&lt;workspace&gt;/...</code></td><td>Agent Sandbox API</td></tr></tbody></table><p>A key only authorizes the exact routes it was scoped to at creation. A request to a path outside the key&#39;s scope is rejected even if the key is otherwise valid. See <a href="./api_keys.html#create-a-key">API Keys</a> for how scopes are selected.</p><h2 id="public-vs-internal-traffic" tabindex="-1">Public vs. Internal Traffic <a class="header-anchor" href="#public-vs-internal-traffic" aria-label="Permalink to &quot;Public vs. Internal Traffic&quot;">​</a></h2><p>Agent Gateway separates two kinds of callers:</p><ul><li><strong>Public</strong>: external clients calling a <code>/ai</code>, <code>/serving</code>, <code>/mcp</code>, <code>/a2a</code>, or <code>/sandbox</code> path with an API key. This is what SDKs, CI jobs, and external integrations use.</li><li><strong>Internal</strong>: workloads running inside the same workspace (for example, an agent calling another service in-cluster) are authorized by their Kubernetes/mesh identity instead of an API key. This path is automatic for in-cluster workloads and does not require you to create or manage a key.</li></ul><p>You only need to think about API keys for the public path.</p><h2 id="managing-access" tabindex="-1">Managing Access <a class="header-anchor" href="#managing-access" aria-label="Permalink to &quot;Managing Access&quot;">​</a></h2><p>API keys are the unit of access control for Agent Gateway. Create, scope, rotate, and disable them from the <strong>API Keys</strong> sidebar page. Each key belongs to one workspace and, optionally, to a specific set of services in that workspace.</p><p>See <a href="./api_keys.html">API Keys</a> for the full create/edit/rotate/disable workflow, client authentication formats, and troubleshooting.</p><h2 id="usage-dashboard" tabindex="-1">Usage Dashboard <a class="header-anchor" href="#usage-dashboard" aria-label="Permalink to &quot;Usage Dashboard&quot;">​</a></h2><p>The API Keys page also has a <strong>Usage</strong> tab showing request volume, LLM token/cost estimates, and per-key activity for the selected workspace. Any workspace member can see this. Administrators additionally see aggregate-only traffic that isn&#39;t tied to a specific key. See <a href="./api_keys.html#usage-dashboard">Usage Dashboard</a> for details.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../agentops/agent_gateway.html">Agent Gateway for AgentOps</a></li><li><a href="./api_keys.html">API Keys</a></li><li><a href="./../mlops/model_serving.html">Model Serving</a></li><li><a href="./../mlops/knative.html">Serverless</a></li><li><a href="./../agentops/mcp_servers.html">MCP Servers</a></li><li><a href="./../agentops/sandboxes.html">Agent Sandboxes</a></li><li><a href="./../admin/external_models.html">External Models</a></li></ul>',23)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
